/**
 * A person's name as the Daily Summary shows it: the Staff record's name, else the login name. Never decorated — no role
 * hint, no brackets, no trimming. Signers, "Generated by" and the collected-by-staff table use THIS one function. The deduction
 * authoriser inside `dailySummary()` (reports.ts) keeps its own inline `staff?.name ?? username`: that function and its data are
 * pinned byte for byte by the golden masters, so it is not touched. The two rules are the same.
 */
export const displayName = (u: { username: string; staff?: { name: string } | null }): string => u.staff?.name ?? u.username;
